// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address actor) public {
        // The pause state of C is only changed via pause()/unpause(), both of which
        // are access-controlled and have never been called on the fresh deployment.
        // Therefore paused() must report the actual (false) internal state for any
        // caller and any input; the mutant unconditionally returns true.
        vm.prank(actor);
        assertTrue(!c.paused(), "contract must not report itself as paused");
    }
}
